[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>SnapFrame — Capture, Create & Share What You Love</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after {
      margin: 0;
      padding: 0;
      box-sizing: border-box;
    }

    :root {
      --black: #000000;
      --purple: #7638FA;
      --purple-light: #9B7DFF;
      --orange: #FF7A00;
      --orange-light: #FF9A3D;
      --pink: #FF3B7A;
      --white: #FFFFFF;
      --gray-100: #F5F5F7;
      --gray-200: #E5E5E7;
      --gray-300: #D1D1D5;
      --gray-500: #86868B;
      --gray-600: #6E6E73;
      --gray-700: #424245;
      --text-primary: #1D1D1F;
      --text-secondary: #6E6E73;
    }

    html {
      scroll-behavior: smooth;
    }

    body {
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
      background: var(--white);
      color: var(--text-primary);
      line-height: 1.5;
      overflow-x: hidden;
    }

    a {
      text-decoration: none;
      color: inherit;
    }

    /* Header */
    .header {
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      z-index: 1000;
      background: rgba(255, 255, 255, 0.85);
      backdrop-filter: blur(20px);
      -webkit-backdrop-filter: blur(20px);
      border-bottom: 1px solid rgba(0, 0, 0, 0.05);
    }

    .header-inner {
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 24px;
      height: 64px;
      display: flex;
      align-items: center;
      justify-content: space-between;
    }

    .logo {
      font-weight: 800;
      font-size: 22px;
      color: var(--black);
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .logo-icon {
      width: 32px;
      height: 32px;
      background: linear-gradient(135deg, var(--purple), var(--pink));
      border-radius: 10px;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .logo-icon svg {
      width: 20px;
      height: 20px;
      fill: white;
    }

    .nav-desktop {
      display: flex;
      align-items: center;
      gap: 32px;
    }

    .nav-link {
      font-size: 14px;
      font-weight: 500;
      color: var(--text-secondary);
      transition: color 0.2s;
    }

    .nav-link:hover {
      color: var(--text-primary);
    }

    .btn-login {
      background: var(--black);
      color: var(--white);
      font-size: 14px;
      font-weight: 600;
      padding: 10px 20px;
      border-radius: 24px;
      border: none;
      cursor: pointer;
      transition: transform 0.2s, opacity 0.2s;
    }

    .btn-login:hover {
      opacity: 0.85;
    }

    .hamburger {
      display: none;
      flex-direction: column;
      justify-content: center;
      gap: 5px;
      width: 32px;
      height: 32px;
      cursor: pointer;
      padding: 4px;
      background: none;
      border: none;
    }

    .hamburger span {
      width: 22px;
      height: 2px;
      background: var(--black);
      border-radius: 2px;
      transition: all 0.3s ease;
    }

    .hamburger.active span:nth-child(1) {
      transform: rotate(45deg) translate(5px, 5px);
    }

    .hamburger.active span:nth-child(2) {
      opacity: 0;
    }

    .hamburger.active span:nth-child(3) {
      transform: rotate(-45deg) translate(5px, -5px);
    }

    /* Mobile Navigation Overlay */
    .nav-mobile {
      display: none;
      position: fixed;
      top: 64px;
      left: 0;
      right: 0;
      bottom: 0;
      background: var(--white);
      padding: 32px 24px;
      flex-direction: column;
      gap: 24px;
      z-index: 999;
      opacity: 0;
      visibility: hidden;
      transition: opacity 0.3s, visibility 0.3s;
    }

    .nav-mobile.active {
      opacity: 1;
      visibility: visible;
    }

    .nav-mobile a {
      font-size: 18px;
      font-weight: 500;
      color: var(--text-primary);
      padding: 12px 0;
      border-bottom: 1px solid var(--gray-200);
    }

    .nav-mobile .btn-login {
      margin-top: 16px;
      text-align: center;
    }

    /* Hero Section */
    .hero {
      min-height: 100vh;
      display: flex;
      align-items: center;
      padding: 120px 24px 80px;
      background: linear-gradient(160deg, #FFF5F5 0%, #F0E6FF 50%, #FFF0E6 100%);
      position: relative;
      overflow: hidden;
    }

    .hero::before {
      content: '';
      position: absolute;
      top: -50%;
      right: -20%;
      width: 80%;
      height: 150%;
      background: radial-gradient(ellipse, rgba(118, 56, 250, 0.15) 0%, transparent 70%);
      pointer-events: none;
    }

    .hero::after {
      content: '';
      position: absolute;
      bottom: -30%;
      left: -10%;
      width: 60%;
      height: 100%;
      background: radial-gradient(ellipse, rgba(255, 122, 0, 0.1) 0%, transparent 70%);
      pointer-events: none;
    }

    .hero-inner {
      max-width: 1200px;
      margin: 0 auto;
      width: 100%;
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 64px;
      align-items: center;
    }

    .hero-content {
      position: relative;
      z-index: 1;
    }

    .hero-title {
      font-size: clamp(36px, 5vw, 64px);
      font-weight: 800;
      line-height: 1.1;
      color: var(--black);
      margin-bottom: 24px;
    }

    .hero-title .gradient-text {
      background: linear-gradient(135deg, var(--purple), var(--pink), var(--orange));
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }

    .hero-description {
      font-size: 18px;
      color: var(--text-secondary);
      margin-bottom: 32px;
      max-width: 480px;
    }

    .btn-primary {
      background: linear-gradient(135deg, var(--purple), var(--pink));
      color: var(--white);
      font-size: 16px;
      font-weight: 700;
      padding: 16px 32px;
      border-radius: 30px;
      border: none;
      cursor: pointer;
      display: inline-flex;
      align-items: center;
      gap: 8px;
      transition: transform 0.2s, box-shadow 0.2s;
    }

    .btn-primary:hover {
      transform: translateY(-2px);
      box-shadow: 0 8px 30px rgba(118, 56, 250, 0.3);
    }

    .hero-visual {
      position: relative;
      z-index: 1;
      display: flex;
      justify-content: center;
    }

    .phone-mockup {
      width: 280px;
      height: 560px;
      background: var(--black);
      border-radius: 40px;
      padding: 12px;
      box-shadow: 0 40px 80px rgba(0, 0, 0, 0.2);
    }

    .phone-screen {
      width: 100%;
      height: 100%;
      background: linear-gradient(180deg, var(--purple) 0%, var(--pink) 50%, var(--orange) 100%);
      border-radius: 32px;
      overflow: hidden;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .phone-screen span {
      font-size: 80px;
      opacity: 0.3;
    }

    /* Section Styles */
    .section {
      padding: 100px 24px;
    }

    .section-inner {
      max-width: 1200px;
      margin: 0 auto;
    }

    .section-label {
      font-size: 12px;
      font-weight: 700;
      letter-spacing: 1px;
      text-transform: uppercase;
      color: var(--purple);
      margin-bottom: 16px;
    }

    .section-headline {
      font-size: clamp(28px, 4vw, 48px);
      font-weight: 800;
      line-height: 1.15;
      color: var(--black);
      margin-bottom: 20px;
    }

    .section-headline a {
      color: var(--purple);
      transition: color 0.2s;
    }

    .section-headline a:hover {
      color: var(--pink);
    }

    .section-description {
      font-size: 18px;
      color: var(--text-secondary);
      max-width: 560px;
      line-height: 1.6;
    }

    .section-link {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      font-size: 16px;
      font-weight: 600;
      color: var(--purple);
      margin-top: 24px;
      transition: gap 0.2s;
    }

    .section-link:hover {
      gap: 10px;
    }

    /* Features Section */
    .features {
      background: var(--white);
    }

    .features-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 24px;
      margin-top: 60px;
    }

    .feature-card {
      background: var(--gray-100);
      border-radius: 20px;
      padding: 32px;
      transition: transform 0.2s, box-shadow 0.2s;
    }

    .feature-card:hover {
      transform: translateY(-4px);
      box-shadow: 0 12px 40px rgba(0, 0, 0, 0.08);
    }

    .feature-icon {
      width: 56px;
      height: 56px;
      border-radius: 16px;
      display: flex;
      align-items: center;
      justify-content: center;
      margin-bottom: 20px;
      font-size: 24px;
    }

    .feature-icon.purple {
      background: linear-gradient(135deg, rgba(118, 56, 250, 0.15), rgba(118, 56, 250, 0.05));
    }

    .feature-icon.orange {
      background: linear-gradient(135deg, rgba(255, 122, 0, 0.15), rgba(255, 122, 0, 0.05));
    }

    .feature-icon.pink {
      background: linear-gradient(135deg, rgba(255, 59, 122, 0.15), rgba(255, 59, 122, 0.05));
    }

    .feature-icon.blue {
      background: linear-gradient(135deg, rgba(59, 130, 246, 0.15), rgba(59, 130, 246, 0.05));
    }

    .feature-title {
      font-size: 18px;
      font-weight: 700;
      color: var(--black);
      margin-bottom: 8px;
    }

    .feature-desc {
      font-size: 14px;
      color: var(--text-secondary);
      line-height: 1.5;
    }

    /* Safety Section */
    .safety {
      background: linear-gradient(180deg, #F8F7FF 0%, var(--white) 100%);
    }

    .safety-content {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 80px;
      align-items: center;
    }

    .safety-visual {
      display: flex;
      justify-content: center;
    }

    .safety-card {
      background: var(--white);
      border-radius: 24px;
      padding: 40px;
      box-shadow: 0 20px 60px rgba(0, 0, 0, 0.08);
      text-align: center;
      width: 320px;
    }

    .safety-card-icon {
      width: 80px;
      height: 80px;
      background: linear-gradient(135deg, var(--purple), var(--pink));
      border-radius: 24px;
      display: flex;
      align-items: center;
      justify-content: center;
      margin: 0 auto 24px;
      font-size: 36px;
    }

    .safety-card-title {
      font-size: 20px;
      font-weight: 700;
      color: var(--black);
      margin-bottom: 8px;
    }

    .safety-card-desc {
      font-size: 14px;
      color: var(--text-secondary);
    }

    /* Creators Section */
    .creators {
      background: linear-gradient(160deg, #1D1D1F 0%, #2D1B4E 50%, #1D1D1F 100%);
      color: var(--white);
      position: relative;
      overflow: hidden;
    }

    .creators::before {
      content: '';
      position: absolute;
      top: -50%;
      right: -20%;
      width: 80%;
      height: 150%;
      background: radial-gradient(ellipse, rgba(118, 56, 250, 0.3) 0%, transparent 70%);
      pointer-events: none;
    }

    .creators-content {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 80px;
      align-items: center;
      position: relative;
      z-index: 1;
    }

    .creators .section-headline {
      color: var(--white);
    }

    .creators .section-description {
      color: rgba(255, 255, 255, 0.7);
    }

    .creators .section-link {
      color: var(--orange);
    }

    .creators-visual {
      display: flex;
      justify-content: center;
    }

    .creator-stats {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 24px;
    }

    .stat-card {
      background: rgba(255, 255, 255, 0.1);
      backdrop-filter: blur(10px);
      border-radius: 20px;
      padding: 28px;
      text-align: center;
    }

    .stat-number {
      font-size: 40px;
      font-weight: 800;
      background: linear-gradient(135deg, var(--purple), var(--pink), var(--orange));
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }

    .stat-label {
      font-size: 14px;
      color: rgba(255, 255, 255, 0.6);
      margin-top: 4px;
    }

    /* Tagline Banner */
    .tagline-banner {
      background: linear-gradient(90deg, var(--purple), var(--pink), var(--orange));
      padding: 60px 24px;
      text-align: center;
    }

    .tagline-text {
      font-size: clamp(28px, 4vw, 48px);
      font-weight: 800;
      color: var(--white);
    }

    /* News Section */
    .news {
      background: var(--gray-100);
    }

    .news-header {
      display: flex;
      justify-content: space-between;
      align-items: flex-end;
      margin-bottom: 40px;
    }

    .news-view-more {
      font-size: 14px;
      font-weight: 600;
      color: var(--purple);
      display: flex;
      align-items: center;
      gap: 6px;
    }

    .news-view-more:hover {
      gap: 10px;
    }

    .news-carousel {
      display: flex;
      gap: 24px;
      overflow-x: auto;
      scroll-snap-type: x mandatory;
      -webkit-overflow-scrolling: touch;
      scrollbar-width: none;
      padding-bottom: 20px;
      margin: 0 -24px;
      padding-left: 24px;
      padding-right: 24px;
    }

    .news-carousel::-webkit-scrollbar {
      display: none;
    }

    .news-card {
      flex: 0 0 320px;
      background: var(--white);
      border-radius: 20px;
      overflow: hidden;
      scroll-snap-align: start;
      transition: transform 0.2s, box-shadow 0.2s;
    }

    .news-card:hover {
      transform: translateY(-4px);
      box-shadow: 0 12px 40px rgba(0, 0, 0, 0.1);
    }

    .news-thumbnail {
      width: 100%;
      height: 180px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 48px;
    }

    .news-thumbnail.t1 {
      background: linear-gradient(135deg, var(--purple), var(--pink));
    }

    .news-thumbnail.t2 {
      background: linear-gradient(135deg, var(--orange), var(--pink));
    }

    .news-thumbnail.t3 {
      background: linear-gradient(135deg, var(--pink), var(--purple));
    }

    .news-thumbnail.t4 {
      background: linear-gradient(135deg, var(--orange), var(--purple));
    }

    .news-content {
      padding: 24px;
    }

    .news-tags {
      display: flex;
      gap: 8px;
      margin-bottom: 12px;
      flex-wrap: wrap;
    }

    .news-tag {
      font-size: 11px;
      font-weight: 700;
      padding: 4px 10px;
      border-radius: 12px;
      background: var(--gray-100);
      color: var(--text-secondary);
    }

    .news-tag.purple {
      background: rgba(118, 56, 250, 0.1);
      color: var(--purple);
    }

    .news-title {
      font-size: 16px;
      font-weight: 600;
      color: var(--black);
      line-height: 1.4;
      margin-bottom: 8px;
    }

    .news-date {
